"""Replay observed data and fixed forward event-transfer experiment; no test tuning."""
import bisect,csv,gzip,hashlib,json,math,statistics
from collections import defaultdict
from datetime import datetime,timezone
from pathlib import Path
import numpy as np
from sklearn.ensemble import GradientBoostingRegressor
from backend.app.domain.stable_swap import quote_swap,get_D
from econometrics import winkler
ROOT=Path(__file__).resolve().parent;OUT=ROOT/'cross_event_study'
TOKENS=['DAI','USDC','USDT'];SCALE=[1e18,1e6,1e6]
# Frozen signatures' keccak-256 topics are generated by the collector.
from collect_cross_event import TOPICS,selected_states

def stamp(s):return int(datetime.fromisoformat(s.replace('Z','+00:00')).timestamp())
def digest(obj):return hashlib.sha256(json.dumps(obj,sort_keys=True,separators=(',',':'),allow_nan=False).encode()).hexdigest()
def save(name,obj):(OUT/name).write_text(json.dumps(obj,separators=(',',':'),allow_nan=False))
def load(name):return json.loads((OUT/name).read_text())
def as_csv(name,rows):
 if not rows:return
 with (OUT/name).open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader()
  for r in rows:w.writerow({k:json.dumps(v) if isinstance(v,(list,dict)) else v for k,v in r.items()})

def decode(e):
 kind=TOPICS.index(e['topics'][0].lower());words=[int(e['data'][i:i+64],16) for i in range(2,len(e['data']),64)]
 r=dict(kind=['swap','add','remove','remove_one','remove_imbalance'][kind],block_number=int(e['blockNumber'],16),transaction_hash=e['transactionHash'],log_index=int(e['logIndex'],16))
 if kind==0:
  i,amount,j,out=words
  if i not in range(3) or j not in range(3):raise ValueError('Invalid token index')
  r.update(sold_id=i,bought_id=j,input_tokens=amount/SCALE[i],output_tokens=out/SCALE[j])
 elif kind in [1,2,4]:r['token_amounts']=[words[i]/SCALE[i] for i in range(3)]
 else:r.update(lp_burned_raw=str(words[0]),output_amount_raw=str(words[1]))
 return r

def build_features():
 groups=selected_states();prices=load('prices_hourly.json');headers={r['block_number']:r for r in load('gas_headers.json')}
 with gzip.open(OUT/'pool_events.json.gz','rt') as f:logs=json.load(f)
 by_event={event:sorted([decode(e) for e in logs if e['collection_event']==event],key=lambda r:(r['block_number'],r['log_index'])) for event in groups}
 all_features=[];exclusions=[];summaries=[]
 for event,states in groups.items():
  source={asset:sorted([p for p in prices if p['event']==event and p['asset']==asset],key=lambda p:p['unix']) for asset in TOKENS}
  price_times={a:[r['unix'] for r in source[a]] for a in TOKENS}
  def at(a,cutoff):
   idx=bisect.bisect_right(price_times[a],cutoff)-1
   return source[a][idx] if idx>=0 and cutoff-source[a][idx]['unix']<=7200 else None
  decoded=by_event[event];blocks=[r['block_number'] for r in decoded];rows=[]
  for previous,state in zip(states,states[1:]):
   cutoff=stamp(state['requested_cutoff_utc']);observed={a:at(a,cutoff) for a in TOKENS}
   if any(p is None for p in observed.values()):
    exclusions.append(dict(event=event,cutoff_utc=state['requested_cutoff_utc'],reason='No preceding USD sample <=2h old for '+','.join(a for a,p in observed.items() if p is None)));continue
   interval=decoded[bisect.bisect_right(blocks,previous['block_number']):bisect.bisect_right(blocks,state['block_number'])]
   marked=[state[a.lower()+'_pool']*observed[a]['price_usd'] for a in TOKENS];tvl=sum(marked)
   vol=lp_add=lp_remove=0.;one=0
   for e in interval:
    if e['kind']=='swap':vol+=e['input_tokens']*observed[TOKENS[e['sold_id']]]['price_usd']
    elif e['kind'] in ['add','remove','remove_imbalance']:
     value=sum(v*observed[a]['price_usd'] for a,v in zip(TOKENS,e['token_amounts']))
     if e['kind']=='add':lp_add+=value
     else:lp_remove+=value
    else:one+=1
   d0=get_D([previous[k] for k in ['dai_pool','usdc_pool','usdt_pool']],previous['amp']);d1=get_D([state[k] for k in ['dai_pool','usdc_pool','usdt_pool']],state['amp'])
   small=quote_swap(state,1,2,1e4);large=quote_swap(state,1,2,1e6)
   row=dict(event=event,cutoff_utc=state['requested_cutoff_utc'],state_utc=state['timestamp'],block_number=state['block_number'],block_hash=state['block_hash'],source_interval_from_block=previous['block_number']+1,source_interval_to_block=state['block_number'],swap_events=sum(e['kind']=='swap' for e in interval),swap_volume_usd=vol,imbalance_ratio=sum(abs(x/tvl-1/3) for x in marked)/2,
       slippage_slope_bps_per_million=(small['average_execution_price_net']-large['average_execution_price_net'])*1e4/.99,lp_add_usd=lp_add,lp_remove_multi_usd=lp_remove,lp_add_pct_tvl=lp_add/tvl*100,lp_remove_multi_pct_tvl=lp_remove/tvl*100,lp_remove_one_events=one,net_invariant_withdrawal_proxy_pct=max(0,1-d1/d0)*100,base_fee_gwei=headers[state['block_number']]['base_fee_gwei'],tvl_marked_usd=tvl,volume_spike=None)
   for asset in TOKENS:
    key=asset.lower();row['price_'+key]=observed[asset]['price_usd'];row['price_'+key+'_observed_at']=observed[asset]['timestamp'];row['price_'+key+'_age_seconds']=cutoff-observed[asset]['unix']
   trailing=rows[-24:]
   if len(trailing)==24 and all(stamp(b['cutoff_utc'])-stamp(a['cutoff_utc'])==3600 for a,b in zip(trailing,trailing[1:])) and stamp(row['cutoff_utc'])-stamp(trailing[-1]['cutoff_utc'])==3600:
    baseline=statistics.mean(r['swap_volume_usd'] for r in trailing)
    if baseline>0:row['volume_spike']=vol/baseline
   rows.append(row)
  all_features+=rows
  summaries.append(dict(event=event,state_cutoffs=len(states),aligned_intervals=len(rows),raw_events=len(decoded),first_cutoff=rows[0]['cutoff_utc'] if rows else None,last_cutoff=rows[-1]['cutoff_utc'] if rows else None,missing_price_intervals=sum(e['event']==event for e in exclusions)))
 save('microstructure_features.json',all_features);as_csv('microstructure_features.csv',all_features);save('alignment_exclusions.json',exclusions);save('coverage.json',summaries)
 print('FEATURES',summaries,flush=True)
 return all_features

def examples(data,asset,protocol):
 result=[];excluded=[]
 for event in protocol['events']:
  rows=sorted([r for r in data if r['event']==event],key=lambda r:r['cutoff_utc'])
  for i in range(6,len(rows)-1):
   window=rows[i-6:i+2];r=rows[i];target=rows[i+1]
   if r['volume_spike'] is None:
    excluded.append(dict(event=event,asset=asset,origin=r['cutoff_utc'],reason='24 contiguous preceding flow intervals unavailable'));continue
   if any(stamp(b['cutoff_utc'])-stamp(a['cutoff_utc'])!=3600 for a,b in zip(window,window[1:])):
    excluded.append(dict(event=event,asset=asset,origin=r['cutoff_utc'],reason='Gap in seven-lag plus next-hour target window'));continue
   # A stale next-cutoff sample that was already known at the origin is not a forecast target.
   if stamp(target['price_'+asset.lower()+'_observed_at'])<=stamp(r['cutoff_utc']):
    excluded.append(dict(event=event,asset=asset,origin=r['cutoff_utc'],reason='Next-cutoff price sample was already known at origin'));continue
   values=[(x['price_'+asset.lower()]-1)*10000 for x in window[:-1]]
   price=[values[-1],values[-2],values[-3],values[-7],statistics.mean(values),statistics.pstdev(values),values[-1]-values[-2]]
   result.append(dict(event=event,asset=asset,origin=r['cutoff_utc'],target=target['cutoff_utc'],target_price_observed_at=target['price_'+asset.lower()+'_observed_at'],actual_bps=(target['price_'+asset.lower()]-1)*10000,persistence_bps=values[-1],price_features=price,covariates=[r[k] for k in protocol['observed_covariates']],stress=abs(target['price_'+asset.lower()]-1)>.01))
 save('example_exclusions_'+asset+'.json',excluded)
 return result

def score_rows(predictions):
 result=[];base=next(np.mean([r['absolute_error_bps'] for r in predictions if r['model']==model]) for model in ['Persistence / zero price change'])
 for model in ['Persistence / zero price change','GB price-only','GB + observed covariates']:
  rs=[r for r in predictions if r['model']==model];errors=np.array([r['absolute_error_bps'] for r in rs]);stress=[r for r in rs if r['stress']]
  result.append(dict(Model=model,Targets=len(rs),MAE_bps=float(errors.mean()),RMSE_bps=float(np.sqrt(np.mean(errors**2))),Max_error_bps=float(errors.max()),Stress_targets=len(stress),Stress_MAE_bps=float(np.mean([r['absolute_error_bps'] for r in stress])) if stress else None,Coverage_pct=float(np.mean([r['lower_bps']<=r['actual_bps']<=r['upper_bps'] for r in rs])*100),Mean_width_bps=float(np.mean([r['upper_bps']-r['lower_bps'] for r in rs])),Winkler_bps=float(np.mean([winkler(r['actual_bps'],r['lower_bps'],r['upper_bps']) for r in rs])),MAE_skill_vs_persistence_pct=100*(1-float(errors.mean())/base) if base else None))
 return result

def run_study(data):
 protocol=load('protocol.json');folds=[]
 for asset in protocol['assets']:
  ex=examples(data,asset,protocol)
  for fold in protocol['folds']:
   train=sorted([r for r in ex if r['event'] in fold['train_events']],key=lambda r:r['origin']);test=[r for r in ex if r['event']==fold['test_event']]
   if len(train)<64 or not test:raise ValueError('Insufficient chronological training/test data')
   fit,cal=train[:-32],train[-32:]
   if max(r['target'] for r in train)>=min(r['origin'] for r in test):raise ValueError('Future event leakage')
   predictions=[];radii={};calibration_predictions=[]
   for model in protocol['models']:
    if model.startswith('Persistence'):
     cal_pred=[r['persistence_bps'] for r in cal];test_pred=[r['persistence_bps'] for r in test]
    else:
     cov=model=='GB + observed covariates'
     design=lambda r:r['price_features']+(r['covariates'] if cov else [])
     reg=GradientBoostingRegressor(**protocol['gb_settings']);reg.fit([design(r) for r in fit],[r['actual_bps'] for r in fit])
     cal_pred=reg.predict([design(r) for r in cal]);test_pred=reg.predict([design(r) for r in test])
    calibration_predictions += [dict(model=model,origin=r['origin'],target=r['target'],actual_bps=r['actual_bps'],prediction_bps=float(p),absolute_residual_bps=abs(float(p)-r['actual_bps'])) for p,r in zip(cal_pred,cal)]
    residuals=sorted(abs(p-r['actual_bps']) for p,r in zip(cal_pred,cal));rank=min(len(cal),math.ceil((len(cal)+1)*.9));radius=float(residuals[rank-1]);radii[model]=radius
    for r,p in zip(test,test_pred):
     p=float(p);predictions.append({k:r[k] for k in ['event','asset','origin','target','target_price_observed_at','actual_bps','stress']}|dict(model=model,prediction_bps=p,absolute_error_bps=abs(p-r['actual_bps']),lower_bps=p-radius,upper_bps=p+radius))
   folds.append(dict(asset=asset,test_event=fold['test_event'],train_events=fold['train_events'],fit_examples=len(fit),calibration_examples=len(cal),test_examples=len(test),fit_start=fit[0]['origin'],fit_end=fit[-1]['target'],calibration_start=cal[0]['origin'],calibration_end=cal[-1]['target'],test_start=min(r['origin'] for r in test),test_end=max(r['target'] for r in test),calibration_radius_bps=radii,calibration_predictions=calibration_predictions,scores=score_rows(predictions),predictions=predictions))
   print('FOLD',asset,fold['test_event'],[(r['Model'],round(r['MAE_skill_vs_persistence_pct'],2)) for r in folds[-1]['scores']],flush=True)
 result=dict(version=protocol['version'],generated_at_utc=datetime.now(timezone.utc).isoformat(timespec='seconds'),protocol_sha256=hashlib.sha256((OUT/'protocol.json').read_bytes()).hexdigest(),feature_sha256=hashlib.sha256((OUT/'microstructure_features.json').read_bytes()).hexdigest(),design=protocol['design'],folds=folds,limitations=['Only two forward test events, one Curve pool; folds and assets are not independent replications.','Events and original model families were previously inspected; no preregistered untouched holdout is claimed.','Frozen pre-event residual intervals can fail coverage under crisis shift; full metrics retained.','No causal identification or structural participant calibration.','Missing or already-known target observations are excluded, not interpolated.','Single-coin LP removal amounts cannot be USD-valued here; counts only.','Gas feature is cutoff-block base fee, not actual transaction gas cost.'])
 save('results.json',result);as_csv('predictions.csv',[r for fold in folds for r in fold['predictions']]);as_csv('scores.csv',[dict(asset=f['asset'],test_event=f['test_event'],**r) for f in folds for r in f['scores']])
 manifest=dict(version='cross-event-1.0',generated_at_utc=result['generated_at_utc'],feature_rows=len(data),coverage=load('coverage.json'),collection=load('collection_manifest.json'),protocol_sha256=result['protocol_sha256'],files={p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in OUT.iterdir() if p.is_file() and p.name!='manifest.json'})
 save('manifest.json',manifest)

if __name__=='__main__':run_study(build_features())
